mapper.select:
SELECT r.repo_id, r.repo_name, r.repo_desc, r.status, r.create_by, r.create_date, r.update_by, r.update_date, cu.user_name AS creator_name, GROUP_CONCAT(u.user_name ORDER BY u.user_name SEPARATOR ',') AS collaborator_names, GROUP_CONCAT(u.user_id ORDER BY u.user_name SEPARATOR ',') AS collaborator_ids_string FROM tt_repo r LEFT JOIN tm_user cu ON r.create_by = cu.user_id AND cu.is_delete = ${@com.sandrew.publish.dictionary.Fixcode@IF_TYPE_NO.getCode()} LEFT JOIN tr_repo_user ru ON r.repo_id = ru.repo_id AND ru.is_delete = ${@com.sandrew.publish.dictionary.Fixcode@IF_TYPE_NO.getCode()} LEFT JOIN tm_user u ON u.user_id = ru.user_id AND u.is_delete = ${@com.sandrew.publish.dictionary.Fixcode@IF_TYPE_NO.getCode()} WHERE r.is_delete = ${@com.sandrew.publish.dictionary.Fixcode@IF_TYPE_NO.getCode()}
AND r.create_by = #{condition.ownerId}
AND r.repo_name LIKE CONCAT('%', #{condition.repoName}, '%')
AND r.status = #{condition.status}
GROUP BY r.repo_id ORDER BY r.repo_id DESC

SELECT module_id, repo_id, module_name, module_desc, url_base, status, create_by, create_date, update_by, update_date FROM tt_module WHERE is_delete = ${@com.sandrew.publish.dictionary.Fixcode@IF_TYPE_NO.getCode()}
AND repo_id = #{condition.repoId}
AND module_name LIKE CONCAT('%', #{condition.moduleName}, '%')
ORDER BY module_id DESC

SELECT api_id, repo_id, module_id, api_name, api_path, invoke_type, status_code, status, testable, create_by, create_date, update_by, update_date FROM tt_api WHERE is_delete = ${@com.sandrew.publish.dictionary.Fixcode@IF_TYPE_NO.getCode()}
AND module_id = #{condition.moduleId}
AND api_name LIKE CONCAT('%', #{condition.apiName}, '%')
ORDER BY api_id DESC
